// План: specs/wallets.md, тест 2.2. Кейс: .qa/tests/wallets/WAL-004. Тикет #6a86f7b6c1d5b42dcc780431.
// Несколько ролей: клиент (0500000004, «יונתן לוי») создаёт общий кошелёк с участником נותן שירות (0500000005, «שירה כהן»).
// Создаёт кошелёк QA-AUTO-… → не @prod-safe. Удаления кошелька в UI нет — id в qa-auto-created.jsonl; участник удаляется в конце.
import { test, expect } from '../../fixtures';
import * as fs from 'fs';
import * as path from 'path';
import { stamp } from '../disputes/helpers';

test.describe.configure({ retries: 0 });

const CREATED_LOG = path.resolve(__dirname, '../../qa-auto-created.jsonl');
const CLIENT_NAME = 'יונתן לוי';
const PROVIDER_NAME = 'שירה כהן';

test.describe('ארנקים משותפים — יצירה', () => {
  test('יצירת ארנק משותף: מופיע אצל היוצר ואצל המשתתף @android #6a86f7b6', async ({ asUser }) => {
    const client = await asUser('client');
    const provider = await asUser('provider');
    const name = `QA-AUTO-ארנק משותף ${stamp()}`;

    // 1. Клиент заполняет форму и добавляет участника по номеру.
    await client.goto('/wallet/shared/new');
    await client.getByRole('textbox', { name: 'שם הארנק' }).fill(name);
    await client.getByRole('button', { name: 'הזמנה מאנשי הקשר' }).click();
    await client.getByRole('textbox', { name: 'מספר הטלפון של המשתתף' }).fill('0500000005');
    const add = client.getByRole('button', { name: 'הוספה' });
    await expect(add).toBeEnabled({ timeout: 15_000 });
    await add.click();
    await expect(client.getByText(PROVIDER_NAME, { exact: true })).toBeVisible();

    await client.getByRole('button', { name: 'אישור ופתיחת ארנק' }).click();
    await client.waitForURL(/\/wallet\/shared\/[0-9a-f-]{20,}/, { timeout: 20_000 });
    const walletId = new URL(client.url()).pathname.split('/wallet/shared/')[1];
    fs.appendFileSync(CREATED_LOG, JSON.stringify({ walletId, title: name, note: 'общий кошелёк (WAL-004)', at: new Date().toISOString() }) + '\n');

    try {
      // 2. Экран кошелька (AC6).
      await expect(client.getByText(name).first()).toBeVisible();
      await expect(client.getByText('יתרה משותפת')).toBeVisible();
      await expect(client.getByText('₪0').first()).toBeVisible();
      await expect(client.getByText('משתתפי הקבוצה (2)')).toBeVisible();
      await expect(client.getByText(CLIENT_NAME, { exact: true })).toBeVisible();
      await expect(client.getByText('מנהל', { exact: true }).first()).toBeVisible();
      await expect(client.getByText(PROVIDER_NAME, { exact: true })).toBeVisible();
      await expect(client.getByText('משתתף', { exact: true }).first()).toBeVisible();

      // 3. Список создателя: «1 מנהלים», «2 משתתפים» (S-46 AC2).
      await client.goto('/wallet/shared');
      const card = client.getByText(name, { exact: true }).first();
      await expect(card).toBeVisible();
      const cardText = await card.locator('xpath=ancestor::*[contains(., "מנהלים")][1]').innerText();
      expect(cardText).toContain('1 מנהלים');
      expect(cardText).toContain('2 משתתפים');

      // 4. Список участника (F-59 AC10): действие одной роли видно другой.
      await provider.goto('/wallet/shared');
      await expect(async () => {
        await provider.reload();
        await expect(provider.getByText(name, { exact: true }).first()).toBeVisible({ timeout: 5_000 });
      }).toPass({ timeout: 60_000, intervals: [1_000, 3_000, 5_000] });
    } finally {
      // Очистка: убрать участника 05 из тестового кошелька.
      await client.goto(`/wallet/shared/${walletId}`);
      const remove = client.getByRole('button', { name: `הסרת ${PROVIDER_NAME}` });
      if (await remove.isVisible({ timeout: 10_000 }).catch(() => false)) {
        await remove.click();
        await client.getByRole('button', { name: 'הסרה', exact: true }).click();
        await expect(client.getByText('משתתפי הקבוצה (1)')).toBeVisible({ timeout: 15_000 });
      }
    }
  });
});
